const D = { energy:.62, density:.5, speed:1, scale:1, cohesion:1.0, separation:1.5, alignment:1.2, reach:.5, wander:.35, predator:.6, trail:.5, hue:26, x:.5, y:.5, style:'murmuration', act:'murmur', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height), key = width+'x'+height, st = P.style, ga = Math.max(0, P.alpha)/100;
const TAU = 6.2831853;
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };

const SW = Math.min(240, Math.max(96, Math.round(width/4)));
const SH = Math.max(54, Math.round(SW*height/Math.max(1,width)));
const skyKey = st+'|'+Math.round(P.hue)+'|'+(P.seed|0)+'|'+SW+'x'+SH;
if (S.skyKey !== skyKey) {
  S.skyKey = skyKey; S.needEstab = true;
  let g2 = S.sky;
  if (!g2 || S.skW!==SW || S.skH!==SH) { g2 = S.sky = createGraphics(SW, SH); g2.pixelDensity(1); S.skW=SW; S.skH=SH; }
  g2.colorMode(g2.HSB, 360, 100, 100, 100);
  g2.noStroke();
  if (st === 'ink') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill(40, 8, 93 - ty*7); g2.rect(0,jy,SW,1); }
    for (let k=0;k<200;k++){ const gx=fr(k*2+1)*SW, gy=fr(k*2+2)*SH; g2.fill(36, 14, 60, 12); const rr=1+fr(k*3+5)*2; g2.ellipse(gx,gy,rr,rr); }
  } else if (st === 'starling-black') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); const tt=ty*ty*(3-2*ty);
      g2.fill((P.hue+18)%360, 14+tt*14, 86 - tt*24); g2.rect(0,jy,SW,1); }
  } else if (st === 'neon-swarm') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); g2.fill((P.hue+205)%360, 66, 3+ty*5); g2.rect(0,jy,SW,1); }
  } else if (st === 'firefly') {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); const tt=ty*ty; g2.fill((P.hue+150)%360, 55, 4+tt*7); g2.rect(0,jy,SW,1); }
  } else {
    for (let jy=0; jy<SH; jy++){ const ty=jy/(SH-1); const tt=ty*ty*(3-2*ty);
      const h=((P.hue+8+tt*44)%360+360)%360; g2.fill(h, 62 - tt*20, 26+tt*34); g2.rect(0,jy,SW,1); }
    g2.blendMode(g2.ADD);
    const sx=P.x*SW, sy=0.72*SH;
    for (let r=0;r<6;r++){ const rr=(0.66-r*0.09)*SW; g2.fill((P.hue+14)%360, 60, 66, 9); g2.ellipse(sx, sy, rr, rr*0.62); }
    g2.blendMode(g2.BLEND);
  }
}

const N = Math.floor(200 + P.density*320);
if (S.seedUsed!==P.seed || S.pkey!==key || !S.ps || S.ps.length!==N){
  S.seedUsed=P.seed; S.pkey=key;
  let z=(P.seed*2654435761+12345)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.ps=[];
  for (let i=0;i<N;i++){ const a=S.rnd()*TAU;
    S.ps.push({ x:S.rnd()*width, y:S.rnd()*height, vx:Math.cos(a)*(0.4+S.rnd()*0.6), vy:Math.sin(a)*(0.4+S.rnd()*0.6) }); }
}
const ps=S.ps, rnd=S.rnd;

const intn = (K.intensity!=null?K.intensity:0.6);
const sweep = 0.5 + 0.5*Math.sin(K.section*0.8 + K.t*0.011);
const cohMul = 0.72 + sweep*0.66 + K.swell*0.28;
const sepMul = 1.16 - sweep*0.3;
const spdMul = 0.84 + intn*0.46;
let predBase = 0.45 + P.predator*0.9;
if (P.act==='startle'){ predBase *= 1.9; }
else if (P.act==='settle'){ predBase *= 0.4; }
const predForce = predBase * (1 + K.pulse*1.1 + A.bass*1.0);
const predx = ((P.x + 0.34*Math.sin(K.t*0.052 + 2.1)) % 1 + 1) % 1 * width;
const predy = ((P.y + 0.30*Math.cos(K.t*0.044 + 0.6)) % 1 + 1) % 1 * height;
const predR = u*(0.14 + P.predator*0.06), predR2 = predR*predR;

const rad = u*(0.034 + P.reach*0.10) * P.scale, rad2 = rad*rad;
const sepR2 = (rad*0.5)*(rad*0.5);
const vmax = u*(0.0038 + P.speed*0.0085) * spdMul, vmin = vmax*0.2;
const wCoh = (0.30 + P.cohesion*1.0) * cohMul;
const wAli = 0.35 + P.alignment*1.25;
const wSep = (0.60 + P.separation*1.6) * sepMul;
const wanderAmt = vmax*(0.05 + P.wander*0.45);
const forceCap = vmax*0.85;
const hw=width*0.5, hh=height*0.5;
const hueDrift = K.t*6;

const cell=Math.max(6,rad), cols=Math.max(1,Math.ceil(width/cell)), rows=Math.max(1,Math.ceil(height/cell));
let grid=S.grid;
if (!grid || S.gc!==cols || S.gr!==rows){ grid=S.grid=new Array(cols*rows); S.gc=cols; S.gr=rows; for (let i=0;i<grid.length;i++) grid[i]=[]; }
for (let i=0;i<grid.length;i++) grid[i].length=0;
const cellOf=(x,y)=>((((Math.floor(x/cell)%cols)+cols)%cols) + (((Math.floor(y/cell)%rows)+rows)%rows)*cols);
for (let i=0;i<N;i++){ const p=ps[i]; grid[cellOf(p.x,p.y)].push(i); }

const fadeA = (16 + P.trail*46) * ga;
blendMode(BLEND); noStroke();
tint(0,0,100, S.needEstab ? 100 : fadeA);
image(S.sky, 0, 0, width, height);
noTint();
S.needEstab = false;

const additive = (st==='neon-swarm' || st==='firefly');
blendMode(additive ? ADD : BLEND);

const bl = u*(0.010 + P.energy*0.013) * P.scale;
const bw = bl*0.6;

for (let i=0;i<N;i++){
  const p=ps[i];
  const cx=(((Math.floor(p.x/cell)%cols)+cols)%cols), cy=(((Math.floor(p.y/cell)%rows)+rows)%rows);
  let sx=0,sy=0, ax=0,ay=0, gx=0,gy=0, cnt=0;
  for (let ox=-1;ox<=1;ox++) for (let oy=-1;oy<=1;oy++){
    const b=grid[((((cx+ox)%cols)+cols)%cols) + (((((cy+oy)%rows)+rows)%rows)*cols)];
    for (let k=0;k<b.length;k++){
      const j=b[k]; if (j===i) continue; const q=ps[j];
      let dx=q.x-p.x, dy=q.y-p.y;
      if (dx>hw)dx-=width; else if (dx<-hw)dx+=width;
      if (dy>hh)dy-=height; else if (dy<-hh)dy+=height;
      const d2=dx*dx+dy*dy; if (d2>rad2||d2<1e-4) continue;
      gx+=dx; gy+=dy; ax+=q.vx; ay+=q.vy;
      if (d2<sepR2){ const inv=1/d2; sx-=dx*inv; sy-=dy*inv; }
      cnt++;
    }
  }
  let accx=0, accy=0;
  if (cnt>0){ const inv=1/cnt;
    accx += gx*inv*wCoh*0.02 + ((ax*inv)-p.vx)*wAli*0.35 + sx*wSep*3.0;
    accy += gy*inv*wCoh*0.02 + ((ay*inv)-p.vy)*wAli*0.35 + sy*wSep*3.0;
  }
  const wa = noise(p.x*0.0016, p.y*0.0016, K.t*0.045 + S.seedUsed*0.017)*TAU*2;
  accx += Math.cos(wa)*wanderAmt; accy += Math.sin(wa)*wanderAmt;
  const am=Math.hypot(accx,accy); if (am>forceCap){ const s=forceCap/am; accx*=s; accy*=s; }
  let pdx=predx-p.x; if(pdx>hw)pdx-=width; else if(pdx<-hw)pdx+=width;
  let pdy=predy-p.y; if(pdy>hh)pdy-=height; else if(pdy<-hh)pdy+=height;
  const pd2=pdx*pdx+pdy*pdy;
  let fright=0;
  if (pd2<predR2 && pd2>1){ const pd=Math.sqrt(pd2); fright=(1-pd/predR); const f=fright*predForce*vmax; accx-=(pdx/pd)*f; accy-=(pdy/pd)*f; }
  p.vx+=accx; p.vy+=accy;
  let sp=Math.hypot(p.vx,p.vy);
  if (sp>vmax){ const s=vmax/sp; p.vx*=s; p.vy*=s; sp=vmax; }
  else if (sp<vmin && sp>1e-4){ const s=vmin/sp; p.vx*=s; p.vy*=s; sp=vmin; }
  if (!isFinite(p.x)||!isFinite(p.y)||!isFinite(p.vx)||!isFinite(p.vy)){ p.x=rnd()*width; p.y=rnd()*height; p.vx=rnd()-0.5; p.vy=rnd()-0.5; sp=vmin; }
  p.x=(p.x+p.vx+width)%width; p.y=(p.y+p.vy+height)%height;

  const isp = 1/(sp||1), ca=p.vx*isp, sa=p.vy*isp, sn=Math.min(1, sp/(vmax||1));
  const nx=p.x+ca*bl, ny=p.y+sa*bl;
  const txc=p.x-ca*bl*0.55, tyc=p.y-sa*bl*0.55;
  const perpx=-sa*bw, perpy=ca*bw;
  const hd=((Math.atan2(sa,ca)/TAU)+1)%1;

  if (st==='murmuration'){
    const h=((P.hue + hd*300 + hueDrift + sn*20)%360+360)%360;
    noStroke();
    fill(h, 58+sn*30, 58+sn*34+fright*8, (78+P.energy*22)*ga);
    triangle(nx,ny, txc+perpx,tyc+perpy, txc-perpx,tyc-perpy);
  } else if (st==='starling-black'){
    noStroke();
    fill((P.hue+10)%360, 16, 6+sn*8, (72+P.energy*22)*ga);
    triangle(nx,ny, txc+perpx,tyc+perpy, txc-perpx,tyc-perpy);
  } else if (st==='neon-swarm'){
    const h=((P.hue + hd*320 + hueDrift)%360+360)%360;
    const al=Math.min(34, (16+P.energy*16+K.pulse*5+fright*10)*ga);
    noStroke();
    fill(h, 88, Math.min(100, 66+sn*34+A.rms*30), al);
    triangle(nx,ny, txc+perpx,tyc+perpy, txc-perpx,tyc-perpy);
  } else if (st==='firefly'){
    const ph=fr(i*7+3);
    const glow=0.5+0.5*Math.sin(K.t*1.4 + ph*TAU + K.beat*0.6);
    const h=((P.hue + 24 + ph*40 + hd*30)%360+360)%360;
    const al=Math.min(32, (10+glow*18+P.energy*10+A.treble*20)*ga);
    noStroke();
    fill(h, 70, Math.min(100, 70+glow*30), al);
    const rr=(bl*0.9)*(0.7+glow*0.6);
    ellipse(p.x, p.y, rr, rr);
    fill(h, 40, 100, al*0.5); ellipse(p.x, p.y, rr*0.4, rr*0.4);
  } else {
    const jj=fr(i);
    noStroke();
    fill(34, 12+jj*10, 8+jj*10, (44+jj*40)*ga);
    const s2=0.8+jj*0.7;
    triangle(p.x+ca*bl*s2, p.y+sa*bl*s2, txc+perpx*s2, tyc+perpy*s2, txc-perpx*s2, tyc-perpy*s2);
  }
}

if (!additive && (P.act!=='settle' || fadeA>0)){
  const pvx=Math.cos(K.t*0.052+2.1), pvy=-Math.sin(K.t*0.044+0.6);
  const pl=bl*2.2, pw=bl*1.4, ip=1/(Math.hypot(pvx,pvy)||1);
  const pca=pvx*ip, psa=pvy*ip;
  noStroke(); fill(st==='ink'?34:(P.hue+8)%360, st==='starling-black'?20:30, st==='ink'?4:10, (34+P.predator*30)*ga);
  triangle(predx+pca*pl, predy+psa*pl, predx-psa*pw-pca*pl*0.4, predy+pca*pw-psa*pl*0.4, predx+psa*pw-pca*pl*0.4, predy-pca*pw-psa*pl*0.4);
}

blendMode(BLEND); noTint(); drawingContext.shadowBlur=0;
